// async keyword makes the function return a Promise
async function getUser(id) {
  // await pauses here until the promise resolves
  const response = await fetch(`/api/users/${id}`);
  const user = await response.json();
  return user;  // returned value is wrapped in a resolved Promise
}

// Call the async function
getUser(1).then(user => console.log(user));

// Or await it inside another async function
async function displayUser() {
  const user = await getUser(1);
  document.querySelector('#name').textContent = user.name;
}

async function loadUserData(userId) {
  try {
    const response = await fetch(`/api/users/${userId}`);

    // HTTP errors don't throw — check manually
    if (!response.ok) {
      throw new Error(`HTTP error: ${response.status}`);
    }

    const user = await response.json();
    return user;

  } catch (error) {
    // Network errors OR the thrown error above
    console.error('Failed to load user:', error.message);
    return null;  // graceful fallback

  } finally {
    // Runs always — hide loading spinner here
    hideSpinner();
  }
}

// SEQUENTIAL — each request waits for the previous (slow: 3×delay)
async function sequential() {
  const user    = await fetchUser();     // 1 second
  const posts   = await fetchPosts();    // 1 second
  const comments = await fetchComments(); // 1 second
  // Total: ~3 seconds
  return { user, posts, comments };
}

// PARALLEL — all requests fire at the same time (fast: 1×max_delay)
async function parallel() {
  const [user, posts, comments] = await Promise.all([
    fetchUser(),
    fetchPosts(),
    fetchComments(),
  ]);
  // Total: ~1 second (whichever is slowest)
  return { user, posts, comments };
}

// async in a for loop — sequential (intentional: each depends on previous)
async function processItems(items) {
  for (const item of items) {
    await processItem(item);  // waits for each before the next
  }
}
